/**
 * archivist for DeepSeek Harness (GENERATED by build/build.mjs from
 * core/archivist.mjs; edit the core, not this file).
 *
 * Registers the archivist_* tools that operate a local, self-maintaining markdown
 * knowledge base (Karpathy LLM Wiki pattern): scaffold/attach a workspace,
 * search/read pages, validated page writes with auto index rebuild, source
 * ingest tracking, structural lint, log, no-git snapshot backup, optional git
 * commit. Deterministic operations only — no network, no API keys. Page
 * content is authored by the host agent following the workspace AGENTS.md schema.
 *
 * Mount via a profile patch insert entry (absolute path to this file).
 * @module scratch-archivist
 */
import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from '@deepseek-ai/dsh-tools'

// ---------------------------------------------------------------------------
// core: single source of truth (embedded by build)
// ---------------------------------------------------------------------------
__CORE__
// ---------------------------------------------------------------------------

export const name = 'scratch-archivist'

export const inject = ['tools']

/** Convert core JSON-schema properties into the dsh parameter spec. */
function toDshParameters(schema: {
  properties?: Record<string, Record<string, unknown>>
  required?: readonly string[]
}): Record<string, Record<string, unknown>> {
  const out: Record<string, Record<string, unknown>> = {}
  for (const [key, prop] of Object.entries(schema.properties ?? {})) {
    out[key] = { ...prop, ...(schema.required?.includes(key) ? { required: true } : {}) }
  }
  return out
}

export function apply(ctx: Context): void {
  setHost('dsh')   // 失败自动上报时标清来源宿主
  for (const tool of TOOLS) {
    ctx.tools.register(defineTool({
      name: tool.name,
      description: tool.description,
      parameters: toDshParameters(tool.schema as {
        properties?: Record<string, Record<string, unknown>>
        required?: readonly string[]
      }),
      output: {
        schema: { type: 'string' },
        render: (_args, value) => [{ type: 'text', text: value }],
      },
      // A tool may exceed the default budget (archivist_index embeds a cold
      // corpus); the table declares its own timeout when it needs one.
      timeoutMs: Number((tool as { timeoutMs?: number }).timeoutMs) || 30000,
      isConcurrencySafe: () => false,
      async execute(args) {
        // Tools that reach the ML sidecar (search/evidence) return a Promise; sync
        // tools return a string. Awaiting either is correct at the adapter boundary.
        return String(await runTool(tool, (args ?? {}) as Record<string, unknown>))
      },
    }))
  }
}
